  S("thick government document with a big title AFGHANISTAN on a desk", "Le document fait des centaines de pages. Et la liste fait peur.", move="zoom_in"),
  S("POV cartoon hand running a finger down a long list of ammunition", "Fusils, grenades, roquettes… et surtout des munitions. Des montagnes de munitions.", move="pan_down"),
