  S("chubby young man explaining with hands, office", ("efraim", "On enlève les vieilles caisses. On met tout dans des cartons neufs. Sans marque."), chars=["efraim"], move="static"),
  S("middle-aged man with mustache listening and nodding in the warehouse", ("arben", "Je connais une usine. Des ouvriers. Ils peuvent faire ça vite."), chars=["arben"], move="zoom_in"),
  S("POV looking at mountains of crates, overwhelming", "Cent millions de cartouches. À déballer et remballer. À la main.", move="pan_up"),
  S("young man sitting alone on a crate, head in hands", "Je sais que c'est mal. Je le sais au fond de moi.", move="zoom_out"),
  S("chubby young man on the phone, voice cold", ("efraim", "Si on livre pas, on perd tout. Ta fille aussi, elle perd tout."), chars=["efraim"], move="push"),
  S("POV cartoon hand slowly closing a flip phone", "Je raccroche. Et je dis à Arben de commencer.", move="static"),
